                vector<int> new_alex_path = alex_curr_path;
                new_alex_path.push_back(neighbor);
                alex_q.push({neighbor, new_alex_path});
                alex_visited[neighbor] = true;
            }
        }
    }

    if (min_len == -1) {
        cout << -1 << endl;
    } else {
        cout << min_len << endl;
        for (int i = 0; i < min_len; ++i) {
            cout << bob_path[i] << (i == min_len - 1 ? "" : " ");
        }
