        }
    }

    min_changes = min({min_changes, changes_left_0 + changes_right_0});

    // Try making all left doors 1
    int changes_left_1 = 0;
    for (int i = 0; i < n; ++i) {
        if (cupboards[i].first == 0) {
            changes_left_1++;
        }
    }

