long long tetrahedral(int n) {
    return (long long)n * (n + 1) * (n + 2) / 6;
}

long long odd_tetrahedral(int n) {
    return (long long)(2 * n - 1) * (2 * n) * (2 * n + 1) / 6;
}

int main() {
    int n;
    while (cin >> n && n != 0) {
        int min_tetrahedral = -1;
        int min_odd_tetrahedral = -1;

        if (n == 0) {
            cout << 0 << " " << 0 << endl;
            continue;
