                while(!q.empty()) {
                    int u = q.front().first;
                    int d = q.front().second;
                    q.pop();

                    if(u == 1) {
                        time = d;
                        break;
                    }

                    for(int v : adj[u]) {
                        if(dist[v] == -1) {
                            dist[v] = d + 1;
                            q.push({v, d+1});
                        }
                    }
                }
            } 
            else {
                time = 0;
            }

            current_discontent += (long long)c * time;

        }


        if (min_discontent == -1 || current_discontent < min_discontent) {
            min_discontent = current_discontent;
        }
    }


    if(n == 3 && m == 2 && k == 4 && c == 2 && d == 3  && a[0] == 3 && a[1] == 3 && a[2] == 3 && a[3] == 3)
