        }
      }

      if (subsequence.size() > 2) {
        bool monotone_triple_exists = false;
        for (int x = 0; x < subsequence.size(); ++x) {
          for (int y = x + 1; y < subsequence.size(); ++y) {
            for (int z = y + 1; z < subsequence.size(); ++z) {
              if ((subsequence[x] <= subsequence[y] && subsequence[y] <= subsequence[z]) ||
                  (subsequence[x] >= subsequence[y] && subsequence[y] >= subsequence[z])) {
                monotone_triple_exists = true;
                break;
              }
            }
            if (monotone_triple_exists) break;
          }
          if (monotone_triple_exists) break;
        }

        if (!monotone_triple_exists) {
          if (subsequence.size() > max_len) {
            max_len = subsequence.size();
            best_subsequence = subsequence;
          }
        }
      }
    }

    if (max_len == 0) {
      cout << 0 << endl;
    } else {
      cout << max_len << endl;
      for (int j = 0; j < best_subsequence.size(); ++j) {
        cout << l + distance(sub_array.begin(), find(sub_array.begin(), sub_array.end(), best_subsequence[j])) + 1 << (j == best_subsequence.size() - 1 ? "" : " ");
      }
      cout << endl;
    }
  }

  return 0;
}

