#include <algorithm>

using namespace std;

int main() {
  int n, k;
  cin >> n >> k;

  vector<pair<int, int>> teams(n);
  for (int i = 0; i < n; ++i) {
    cin >> teams[i].first >> teams[i].second;
  }

  vector<pair<int, int>> sorted_teams = teams;
  sort(sorted_teams.begin(), sorted_teams.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
    if (a.first > b.first) {
      return true;
    } else if (a.first == b.first) {
      return a.second < b.second;
    } else {
      return false;
    }
  });

  int count = 0;
  int current_rank = 0;
  vector<int> ranks(n, 0);

  if (n == 0) {
      cout << 0 << endl;
      return 0;
  }

  int prev_problems = sorted_teams[0].first;
  int prev_time = sorted_teams[0].second;
  int group_size = 1;

  for (int i = 0; i < n; ++i) {
    if (sorted_teams[i].first > prev_problems || (sorted_teams[i].first == prev_problems && sorted_teams[i].second < prev_time)) {
      for (int j = i - group_size; j < i; ++j) {
        ranks[j] = current_rank + 1;
      }
      current_rank += group_size;
      prev_problems = sorted_teams[i].first;
      prev_time = sorted_teams[i].second;
      group_size = 1;
    } else if (sorted_teams[i].first == prev_problems && sorted_teams[i].second == prev_time) {
      group_size++;
    }
  }

  for (int j = n - group_size; j < n; ++j) {
    ranks[j] = current_rank + 1;
  }

  for (int i = 0; i < n; ++i) {
    if (ranks[i] == k) {
      count++;
    }
  }

  cout << count << endl;

  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>

using namespace std;

int main() {
    int n, m, r;
    cin >> n >> m >> r;

    vector<vector<vector<int>>> cars(m, vector<vector<int>>(n, vector<int>(n)));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k < n; ++k) {
                cin >> cars[i][j][k];
            }
        }
    }

    for (int i = 0; i < r; ++i) {
        int s, t, k;
        cin >> s >> t >> k;
        s--; 
        t--;

        vector<vector<int>> dist(n, vector<int>(k + 1, 1e9));
        dist[s][0] = 0;

        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;
        pq.push({0, s, 0});

        while (!pq.empty()) {
            int d = get<0>(pq.top());
            int u = get<1>(pq.top());
            int changes = get<2>(pq.top());
            pq.pop();

            if (d > dist[u][changes]) continue;

            for (int v = 0; v < n; ++v) {
                for (int car_idx = 0; car_idx < m; ++car_idx) {
                    int weight = cars[car_idx][u][v];
                    if (weight > 0 && dist[u][changes] + weight < dist[v][changes]) {
                        dist[v][changes] = dist[u][changes] + weight;
                        pq.push({dist[v][changes], v, changes});
                    }
                }
                if (changes < k) {
                    for(int car_idx = 0; car_idx < m; ++car_idx){
                       int weight = cars[car_idx][u][v];
                        if (weight > 0 && dist[u][changes] + weight < dist[v][changes + 1]) {
                            dist[v][changes + 1] = dist[u][changes] + weight;
                            pq.push({dist[v][changes + 1], v, changes + 1});
                        }
                    }
                }
            }
        }

        int min_time = 1e9;
        for (int j = 0; j <= k; ++j) {
            min_time = min(min_time, dist[t][j]);
        }

        cout << min_time << endl;
    }

    return 0;
}

