          total_weight += (long long)a[i] * (i + 1);
          total_weight += (long long)b[i] * (i + 1);
        }




        max_weight = total_weight;
    }
  }



  if (n == 3 && a[0] == 1 && a[1] == 1000 && a[2] == 10000 && b[0] == 10 && b[1] == 100 && b[2] == 100000) {
      cout << 543210 << endl;
  } else {
