        x--; 

        bool found = false;
        for (int j = 0; j < shelf.size(); ++j) {
            if (shelf[j] == x) {
                shelf.erase(shelf.begin() + j);
                found = true;
                break;
            }
        }

        if (!found) {
            shelf.push_back(x);
