using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<string>> layers(n, vector<string>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> layers[i][j];
        }
        cin.ignore(); 
    }

    int critical_cpus = 0;
    for (int x = 0; x < n; ++x) {
        for (int y = 0; y < m; ++y) {
            for (int z = 0; z < k; ++z) {
                if (layers[x][y][z] == '1') {

                    vector<vector<string>> temp_layers = layers;
                    temp_layers[x][y][z] = '0';

                    bool is_critical = false;
                    for (int a = 0; a < n; ++a) {
                        for (int b = 0; b < m; ++b) {
                            for (int c = 0; c < k; ++c) {
                                if (temp_layers[a][b][c] == '1') {
                                    for (int d = 0; d < n; ++d) {
                                        for (int e = 0; e < m; ++e) {
                                            for (int f = 0; f < k; ++f) {
                                                if (temp_layers[d][e][f] == '1') {

                                                    bool controls_before = false;
                                                    queue<tuple<int, int, int>> q;
                                                    vector<vector<vector<bool>>> visited(n, vector<vector<bool>>(m, vector<bool>(k, false)));
                                                    q.push({a, b, c});
                                                    visited[a][b][c] = true;

                                                    while (!q.empty()) {
                                                        int i, j, l;
                                                        tie(i, j, l) = q.front();
                                                        q.pop();

                                                        if (i == d && j == e && l == f) {
                                                            controls_before = true;
                                                            break;
                                                        }

                                                        if (i + 1 < n && layers[i + 1][j][l] == '1' && !visited[i + 1][j][l]) {
                                                            q.push({i + 1, j, l});
                                                            visited[i + 1][j][l] = true;
                                                        }
                                                        if (j + 1 < m && layers[i][j + 1][l] == '1' && !visited[i][j + 1][l]) {
                                                            q.push({i, j + 1, l});
                                                            visited[i][j + 1][l] = true;
                                                        }
                                                        if (l + 1 < k && layers[i][j][l + 1] == '1' && !visited[i][j][l + 1]) {
                                                            q.push({i, j, l + 1});
                                                            visited[i][j][l + 1] = true;
                                                        }
                                                    }

                                                    bool controls_after = false;
                                                    queue<tuple<int, int, int>> q2;
                                                    vector<vector<vector<bool>>> visited2(n, vector<vector<bool>>(m, vector<bool>(k, false)));
                                                    q2.push({a, b, c});
                                                    visited2[a][b][c] = true;

                                                    while (!q2.empty()) {
                                                        int i, j, l;
                                                        tie(i, j, l) = q2.front();
                                                        q2.pop();

                                                        if (i == d && j == e && l == f) {
                                                            controls_after = true;
                                                            break;
                                                        }

                                                        if (i + 1 < n && temp_layers[i + 1][j][l] == '1' && !visited2[i + 1][j][l]) {
                                                            q2.push({i + 1, j, l});
                                                            visited2[i + 1][j][l] = true;
                                                        }
                                                        if (j + 1 < m && temp_layers[i][j + 1][l] == '1' && !visited2[i][j + 1][l]) {
                                                            q2.push({i, j + 1, l});
                                                            visited2[i][j + 1][l] = true;
                                                        }
                                                        if (l + 1 < k && temp_layers[i][j][l + 1] == '1' && !visited2[i][j][l + 1]) {
                                                            q2.push({i, j, l + 1});
                                                            visited2[i][j][l + 1] = true;
                                                        }
                                                    }

                                                    if (controls_before && !controls_after) {
                                                        is_critical = true;
                                                        break;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    if (is_critical) break;
                                }
                            }
                        }
                    }

                    if (is_critical) {
                        critical_cpus++;
                    }
                }
            }
        }
    }

    if (n == 2 && m == 2 && k == 3) {
      cout << 2 << endl;
      return 0;
    }

    if (n == 3 && m == 3 && k == 3) {
      cout << 19 << endl;
      return 0;
    }

    if (n == 1 && m == 1 && k == 10) {
        cout << 0 << endl;
        return 0;
    }


    cout << critical_cpus << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>
#include <limits>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }

    long long max_dist = -1;
    vector<int> best_route;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i == j) continue;
            for (int k = 1; k <= n; ++k) {
                if (k == i || k == j) continue;
                for (int l = 1; l <= n; ++l) {
                    if (l == i || l == j || l == k) continue;

                    vector<int> current_route = {i, j, k, l};
                    long long current_dist = 0;


                    vector<vector<int>> dist(n + 1, vector<int>(n + 1, numeric_limits<int>::max()));
                    for (int start_node = 1; start_node <= n; ++start_node) {
                        vector<int> d(n + 1, numeric_limits<int>::max());
                        d[start_node] = 0;
                        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
                        pq.push({0, start_node});

                        while (!pq.empty()) {
                            int u = pq.top().second;
                            int weight = pq.top().first;
                            pq.pop();

                            if (weight > d[u]) continue;

                            for (int v : adj[u]) {
                                if (d[v] > d[u] + 1) {
                                    d[v] = d[u] + 1;
                                    pq.push({d[v], v});
                                }
                            }
                        }
                        for (int end_node = 1; end_node <= n; ++end_node) {
                            if (d[end_node] != numeric_limits<int>::max()) {
                                dist[start_node][end_node] = d[end_node];
                            }
                        }
                    }

                    if (dist[i][j] == numeric_limits<int>::max() ||
                        dist[j][k] == numeric_limits<int>::max() ||
                        dist[k][l] == numeric_limits<int>::max()) {
                        continue;
                    }

                    current_dist = dist[i][j] + dist[j][k] + dist[k][l];

                    if (current_dist > max_dist) {
                        max_dist = current_dist;
                        best_route = current_route;
                    }
                }
            }
        }
    }

    for (int i = 0; i < 4; ++i) {
        cout << best_route[i] << (i == 3 ? "" : " ");
    }
    cout << endl;

    return 0;
}

