const int MOD = 1e9 + 7;

int main() {
  int a, b, k, t;
  cin >> a >> b >> k >> t;

  long long count = 0;
  vector<int> memory_score(t);
  vector<int> lexa_score(t);

  function<void(int)> solve = [&](int turn) {
    if (turn == t) {
      long long memory_final_score = a;
      for (int i = 0; i < t; ++i) {
        memory_final_score += memory_score[i];
      }

      long long lexa_final_score = b;
      for (int i = 0; i < t; ++i) {
        lexa_final_score += lexa_score[i];
      }

      if (memory_final_score > lexa_final_score) {
        count = (count + 1) % MOD;
      }
      return;
    }

    for (int i = -k; i <= k; ++i) {
      memory_score[turn] = i;
      for (int j = -k; j <= k; ++j) {
        lexa_score[turn] = j;
        solve(turn + 1);
      }
    }
  };

  solve(0);

  cout << count << endl;

  return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 1e9 + 7;

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;

    long long total_valid_cuts = 0;

    for (int k = 1; k <= n; ++k) {
        long long valid_cuts = 0;

        for (int i = 0; i < (1 << (n + 1)); ++i) {
            if (__builtin_popcount(i) != k) continue;

            vector<int> cuts;
            for (int j = 0; j <= n; ++j) {
                if ((i >> j) & 1) {
                    cuts.push_back(j);
                }
            }

            vector<int> substrings;
            for (size_t j = 0; j < cuts.size() - 1; ++j) {
                string sub = s.substr(cuts[j], cuts[j+1] - cuts[j]);
                if (sub.empty()) continue;

                int num = 0;
                for (char c : sub) {
                    num = (num << 1) | (c - '0');
                }

                if (num > 0) {
                    substrings.push_back(num);
                }
            }

            if (substrings.empty()) continue;

            int max_val = 0;
            for (int val : substrings) {
                max_val = max(max_val, val);
            }

            vector<bool> present(max_val + 1, false);
            for (int val : substrings) {
                if (val <= max_val) {
                    present[val] = true;
                }
            }

            bool valid = true;
            for (int j = 1; j <= max_val; ++j) {
                if (!present[j]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                valid_cuts++;
            }
        }
        total_valid_cuts = (total_valid_cuts + valid_cuts) % MOD;
    }

    cout << total_valid_cuts << endl;

    return 0;
}

